CREATE OR REPLACE FUNCTION public.admin_pay_consignment(p_request_id bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_admin_id uuid;
    v_admin_wallet_id bigint;
    v_seller_wallet_id bigint;

    v_request public.consignment_requests%rowtype;

    v_payout numeric;
    v_admin_balance numeric;
    v_transaction_id bigint;
begin

    v_admin_id := auth.uid();

    if v_admin_id is null then
        return json_build_object(
            'success', false,
            'message', 'Bạn chưa đăng nhập.'
        );
    end if;


    if not exists (
        select 1
        from public.users
        where user_id = v_admin_id
          and lower(role) = 'admin'
    ) then

        return json_build_object(
            'success', false,
            'message', 'Bạn không có quyền Admin.'
        );

    end if;


    select *
    into v_request
    from public.consignment_requests
    where id = p_request_id
    for update;


    if v_request.id is null then
        return json_build_object(
            'success', false,
            'message', 'Không tìm thấy yêu cầu ký gửi.'
        );
    end if;


    if v_request.status <> 'sold' then
        return json_build_object(
            'success', false,
            'message', 'Sản phẩm chưa được ghi nhận là đã bán.'
        );
    end if;


    if v_request.payout_status = 'paid' then
        return json_build_object(
            'success', false,
            'message', 'Khoản tiền này đã được thanh toán.'
        );
    end if;


    v_payout :=
        coalesce(
            v_request.seller_receive,
            v_request.selling_price -
            v_request.service_fee,
            0
        );


    if v_payout <= 0 then
        return json_build_object(
            'success', false,
            'message', 'Số tiền thanh toán không hợp lệ.'
        );
    end if;


    /* Ví Admin */
    select id, balance
    into v_admin_wallet_id, v_admin_balance
    from public.iuh_wallets
    where user_id = v_admin_id
    for update;


    if v_admin_wallet_id is null then
        return json_build_object(
            'success', false,
            'message', 'Không tìm thấy ví Admin.'
        );
    end if;


    if coalesce(v_admin_balance, 0) < v_payout then
        return json_build_object(
            'success', false,
            'message',
            'Ví Admin không đủ số dư để thanh toán.'
        );
    end if;


    /* Ví người ký gửi */
    select id
    into v_seller_wallet_id
    from public.iuh_wallets
    where user_id = v_request.user_id
    for update;


    if v_seller_wallet_id is null then
        return json_build_object(
            'success', false,
            'message',
            'Người ký gửi chưa có ví IUH Wallet.'
        );
    end if;


    /* Trừ ví Admin */
    update public.iuh_wallets
    set
        balance = balance - v_payout,
        updated_at = now()
    where id = v_admin_wallet_id;


    /* Cộng ví người gửi */
    update public.iuh_wallets
    set
        balance = balance + v_payout,
        updated_at = now()
    where id = v_seller_wallet_id;


    /* Giao dịch Admin */
    insert into public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description
    )
    values (
        v_admin_wallet_id,
        v_admin_id,
        'payment',
        'Thanh toán ký gửi',
        v_payout,
        'Chi trả cho người ký gửi #' ||
        v_request.id
    );


    /* Giao dịch người gửi */
    insert into public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description
    )
    values (
        v_seller_wallet_id,
        v_request.user_id,
        'sale',
        'Tiền bán sản phẩm ký gửi',
        v_payout,
        'Nhận tiền bán ký gửi #' ||
        v_request.id
    )
    returning id into v_transaction_id;


    update public.consignment_requests
    set
        status = 'completed',
        payout_status = 'paid',
        paid_at = now(),
        processed_by = v_admin_id,
        updated_at = now()
    where id = p_request_id;


    return json_build_object(
        'success', true,
        'message', 'Đã chuyển tiền vào ví người ký gửi.',
        'amount', v_payout,
        'transaction_id', v_transaction_id
    );

exception
    when others then

        return json_build_object(
            'success', false,
            'message', SQLERRM
        );

end;
$function$

CREATE OR REPLACE FUNCTION public.admin_process_consignment(p_request_id bigint, p_status text, p_note text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_admin_id uuid;
    v_request public.consignment_requests%rowtype;
begin

    v_admin_id := auth.uid();

    if v_admin_id is null then
        return json_build_object(
            'success', false,
            'message', 'Bạn chưa đăng nhập.'
        );
    end if;


    /* Kiểm tra Admin */
    if not exists (
        select 1
        from public.users
        where user_id = v_admin_id
          and lower(role) = 'admin'
    ) then

        return json_build_object(
            'success', false,
            'message', 'Bạn không có quyền Admin.'
        );

    end if;


    /* Khóa yêu cầu */
    select *
    into v_request
    from public.consignment_requests
    where id = p_request_id
    for update;


    if v_request.id is null then
        return json_build_object(
            'success', false,
            'message', 'Không tìm thấy yêu cầu ký gửi.'
        );
    end if;


    /* Không cho thay đổi yêu cầu đã hoàn tất */
    if v_request.status = 'completed' then
        return json_build_object(
            'success', false,
            'message', 'Yêu cầu này đã hoàn tất.'
        );
    end if;


    /* Không cho đổi trạng thái tùy ý */
    if p_status not in (
        'approved',
        'rejected',
        'selling',
        'sold',
        'cancelled'
    ) then

        return json_build_object(
            'success', false,
            'message', 'Trạng thái không hợp lệ.'
        );

    end if;


    /* Chỉ pending mới được duyệt / từ chối */
    if p_status in ('approved', 'rejected')
       and v_request.status <> 'pending' then

        return json_build_object(
            'success', false,
            'message', 'Yêu cầu này không còn ở trạng thái chờ duyệt.'
        );

    end if;


    /* Chuyển sang đang bán */
    if p_status = 'selling'
       and v_request.status <> 'approved' then

        return json_build_object(
            'success', false,
            'message', 'Chỉ yêu cầu đã duyệt mới được chuyển sang đang bán.'
        );

    end if;


    /* Ghi nhận đã bán */
    if p_status = 'sold'
       and v_request.status not in ('approved', 'selling') then

        return json_build_object(
            'success', false,
            'message', 'Yêu cầu chưa thể chuyển sang đã bán.'
        );

    end if;


    update public.consignment_requests
    set
        status = p_status,
        admin_note = coalesce(p_note, admin_note),
        processed_by = v_admin_id,
        reviewed_by = v_admin_id,
        reviewed_at = case
            when p_status in ('approved', 'rejected')
            then now()
            else reviewed_at
        end,
        sold_at = case
            when p_status = 'sold'
            then now()
            else sold_at
        end,
        updated_at = now()
    where id = p_request_id;


    return json_build_object(
        'success', true,
        'message', 'Đã cập nhật yêu cầu ký gửi.',
        'status', p_status
    );

exception
    when others then

        return json_build_object(
            'success', false,
            'message', SQLERRM
        );

end;
$function$

CREATE OR REPLACE FUNCTION public.admin_record_consignment_sale(p_request_id bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_admin_id uuid;
    v_admin_wallet_id bigint;
    v_request public.consignment_requests%rowtype;
    v_sale_amount numeric;
begin

    v_admin_id := auth.uid();

    if v_admin_id is null then
        return json_build_object(
            'success', false,
            'message', 'Bạn chưa đăng nhập.'
        );
    end if;


    if not exists (
        select 1
        from public.users
        where user_id = v_admin_id
          and lower(role) = 'admin'
    ) then

        return json_build_object(
            'success', false,
            'message', 'Bạn không có quyền Admin.'
        );

    end if;


    select *
    into v_request
    from public.consignment_requests
    where id = p_request_id
    for update;


    if v_request.id is null then
        return json_build_object(
            'success', false,
            'message', 'Không tìm thấy yêu cầu.'
        );
    end if;


    if v_request.status <> 'sold' then
        return json_build_object(
            'success', false,
            'message', 'Yêu cầu chưa ở trạng thái đã bán.'
        );
    end if;


    /* Nếu đã ghi nhận rồi thì không ghi lần 2 */
    if v_request.payout_status <> 'unpaid' then
        return json_build_object(
            'success', false,
            'message', 'Khoản bán này đã được ghi nhận.'
        );
    end if;


    select id
    into v_admin_wallet_id
    from public.iuh_wallets
    where user_id = v_admin_id
    for update;


    if v_admin_wallet_id is null then
        return json_build_object(
            'success', false,
            'message', 'Không tìm thấy ví Admin.'
        );
    end if;


    v_sale_amount :=
        coalesce(v_request.selling_price, 0);


    if v_sale_amount <= 0 then
        return json_build_object(
            'success', false,
            'message', 'Giá bán không hợp lệ.'
        );
    end if;


    /* Tiền người mua trả vào ví Admin */
    update public.iuh_wallets
    set
        balance = balance + v_sale_amount,
        updated_at = now()
    where id = v_admin_wallet_id;


    insert into public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description
    )
    values (
        v_admin_wallet_id,
        v_admin_id,
        'sale',
        'Tiền bán ký gửi',
        v_sale_amount,
        'Ghi nhận tiền bán sản phẩm ký gửi #' ||
        v_request.id
    );

    insert into public.wallet_transactions (
    wallet_id,
    user_id,
    type,
    title,
    amount,
    description
)
values (
    v_admin_wallet_id,
    v_admin_id,
    'fee',
    'Phí ký gửi',
    coalesce(v_request.service_fee, 0),
    'Phí ký gửi 10% sản phẩm #' ||
    v_request.id
);

    return json_build_object(
        'success', true,
        'message', 'Đã ghi nhận tiền bán vào ví Admin.',
        'amount', v_sale_amount
    );

exception
    when others then

        return json_build_object(
            'success', false,
            'message', SQLERRM
        );

end;
$function$

CREATE OR REPLACE FUNCTION public.create_simulated_donation(p_amount numeric, p_donor_name text DEFAULT NULL::text, p_bank_name text DEFAULT NULL::text, p_transfer_content text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_user_id uuid;
    v_admin_user_id uuid;
    v_admin_wallet_id bigint;

    v_amount numeric;
    v_donor_name text;
    v_bank_name text;
    v_transfer_content text;
    v_transfer_code text;
    v_donation_id bigint;
begin

    v_user_id := auth.uid();

    v_amount :=
        round(
            coalesce(p_amount, 0),
            2
        );


    /* =========================================
       KIỂM TRA SỐ TIỀN
    ========================================= */

    if v_amount < 1000 then

        return json_build_object(
            'success',
            false,
            'message',
            'Số tiền Donate tối thiểu là 1.000đ.'
        );

    end if;


    /* =========================================
       TÊN NGƯỜI DONATE
    ========================================= */

    v_donor_name :=
        nullif(
            trim(
                coalesce(
                    p_donor_name,
                    ''
                )
            ),
            ''
        );


    if v_donor_name is null then

        return json_build_object(
            'success',
            false,
            'message',
            'Vui lòng nhập họ và tên.'
        );

    end if;


    /* =========================================
       NGÂN HÀNG
    ========================================= */

    v_bank_name :=
        nullif(
            trim(
                coalesce(
                    p_bank_name,
                    ''
                )
            ),
            ''
        );


    if v_bank_name is null then

        return json_build_object(
            'success',
            false,
            'message',
            'Vui lòng chọn ngân hàng.'
        );

    end if;


    /* =========================================
       NỘI DUNG
    ========================================= */

    v_transfer_content :=
        nullif(
            trim(
                coalesce(
                    p_transfer_content,
                    ''
                )
            ),
            ''
        );


    if v_transfer_content is null then

        v_transfer_content :=
            'DONATE IUH SHOP';

    end if;


    /* =========================================
       MÃ GIAO DỊCH
    ========================================= */

    v_transfer_code :=
        'DONATE-' ||
        to_char(
            now(),
            'YYYYMMDDHH24MISSMS'
        ) ||
        '-' ||
        upper(
            substr(
                md5(
                    random()::text ||
                    clock_timestamp()::text
                ),
                1,
                5
            )
        );


    /* =========================================
       TÌM VÍ ADMIN
    ========================================= */

    select
        w.id,
        w.user_id

    into
        v_admin_wallet_id,
        v_admin_user_id

    from public.iuh_wallets w

    join public.users u
        on u.user_id = w.user_id

    where lower(u.role) = 'admin'

    limit 1

    for update;


    if v_admin_wallet_id is null then

        return json_build_object(
            'success',
            false,
            'message',
            'Không tìm thấy Ví Admin.'
        );

    end if;


    /* =========================================
       LƯU DONATE
    ========================================= */

    insert into public.donations (
        donor_id,
        donor_name,
        amount,
        payment_method,
        transfer_code,
        status,
        note,
        bank_name,
        transfer_content
    )

    values (
        v_user_id,
        v_donor_name,
        v_amount,
        'simulated_bank_transfer',
        v_transfer_code,
        'completed',
        'Donate mô phỏng cho IUH SHOP',
        v_bank_name,
        v_transfer_content
    )

    returning id
    into v_donation_id;


    /* =========================================
       CỘNG TIỀN CHO ADMIN
    ========================================= */

    update public.iuh_wallets

    set
        balance =
            balance + v_amount,

        updated_at =
            now()

    where id = v_admin_wallet_id;


    /* =========================================
       GHI NHẬN DOANH THU ADMIN
    ========================================= */

    insert into public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description
    )

    values (
        v_admin_wallet_id,
        v_admin_user_id,
        'fee',
        'Donate IUH SHOP',
        v_amount,
        'Donate từ ' ||
        v_donor_name ||
        ' - ' ||
        v_bank_name ||
        ' - mã giao dịch ' ||
        v_transfer_code
    );


    /* =========================================
       TRẢ KẾT QUẢ
    ========================================= */

    return json_build_object(
        'success',
        true,

        'message',
        'Donate thành công.',

        'donation_id',
        v_donation_id,

        'transfer_code',
        v_transfer_code,

        'amount',
        v_amount,

        'created_at',
        now()
    );


exception

    when others then

        return json_build_object(
            'success',
            false,
            'message',
            SQLERRM
        );

end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_iuh_wallet()
 RETURNS iuh_wallets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_wallet public.iuh_wallets;
begin

    if auth.uid() is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;


    insert into public.iuh_wallets(user_id)
    values(auth.uid())

    on conflict(user_id)
    do nothing;


    select *
    into v_wallet

    from public.iuh_wallets

    where user_id = auth.uid();


    return v_wallet;

end;
$function$

CREATE OR REPLACE FUNCTION public.expire_service_packages()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.status = 'active' and new.expires_at <= now() then
        new.status = 'expired';
    end if;
    return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.pay_boost_fee()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid;
    v_seller_wallet_id bigint;
    v_admin_wallet_id bigint;

    v_seller_balance numeric;
    v_boost_fee numeric := 3000;
begin

    -- Người đang đăng nhập
    v_user_id := auth.uid();

    if v_user_id is null then
        return json_build_object(
            'success', false,
            'message', 'Bạn chưa đăng nhập.'
        );
    end if;


    -- Tìm ví người dùng
    select id, balance
    into v_seller_wallet_id, v_seller_balance
    from public.iuh_wallets
    where user_id = v_user_id
    for update;


    if v_seller_wallet_id is null then
        return json_build_object(
            'success', false,
            'message', 'Không tìm thấy ví IUH.'
        );
    end if;


    -- Kiểm tra số dư
    if coalesce(v_seller_balance, 0) < v_boost_fee then
        return json_build_object(
            'success', false,
            'message', 'Số dư ví không đủ 3.000đ.'
        );
    end if;


    -- Tìm ví Admin
    select w.id
    into v_admin_wallet_id
    from public.iuh_wallets w
    join public.users u
        on u.user_id = w.user_id
    where lower(u.role) = 'admin'
    order by w.id
    limit 1
    for update;


    if v_admin_wallet_id is null then
        return json_build_object(
            'success', false,
            'message', 'Không tìm thấy ví Admin.'
        );
    end if;


    -- Trừ tiền người bán
    update public.iuh_wallets
    set
        balance = balance - v_boost_fee,
        updated_at = now()
    where id = v_seller_wallet_id;


    -- Ghi giao dịch của người bán
    insert into public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description
    )
    values (
        v_seller_wallet_id,
        v_user_id,
        'payment',
        'Thanh toán phí đẩy tin',
        v_boost_fee,
        'Thanh toán phí đẩy tin nổi bật 24 giờ'
    );


    -- Cộng tiền vào ví Admin
    update public.iuh_wallets
    set
        balance = balance + v_boost_fee,
        updated_at = now()
    where id = v_admin_wallet_id;


    -- Ghi giao dịch doanh thu cho Admin
    insert into public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description
    )
    select
        w.id,
        w.user_id,
        'fee',
        'Phí đẩy tin',
        v_boost_fee,
        'Phí đẩy tin nổi bật 24 giờ'
    from public.iuh_wallets w
    where w.id = v_admin_wallet_id;


    return json_build_object(
        'success', true,
        'message', 'Thanh toán phí đẩy tin thành công.',
        'amount', v_boost_fee
    );

exception
    when others then

        return json_build_object(
            'success', false,
            'message', SQLERRM
        );

end;
$function$

CREATE OR REPLACE FUNCTION public.pay_iuh_wallet(p_amount numeric, p_description text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_wallet public.iuh_wallets;
    v_balance numeric;
begin

    if auth.uid() is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;


    if p_amount is null
       or p_amount <= 0 then

        raise exception
            'Số tiền thanh toán không hợp lệ.';

    end if;


    insert into public.iuh_wallets(user_id)
    values(auth.uid())

    on conflict(user_id)
    do nothing;


    select *
    into v_wallet

    from public.iuh_wallets

    where user_id = auth.uid()

    for update;


    if v_wallet.balance < p_amount then

        raise exception
            'Số dư Ví IUH không đủ.';

    end if;


    v_balance =
        v_wallet.balance - p_amount;


    update public.iuh_wallets

    set
        balance = v_balance,
        updated_at = now()

    where id = v_wallet.id;


    insert into public.wallet_transactions(
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description
    )

    values(
        v_wallet.id,
        auth.uid(),
        'payment',
        'Thanh toán đơn hàng',
        p_amount,
        coalesce(
            p_description,
            'Thanh toán tại IUH SHOP'
        )
    );


    return v_balance;

end;
$function$

CREATE OR REPLACE FUNCTION public.pay_platform_fee(p_amount numeric, p_description text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id uuid;
    v_user_wallet public.iuh_wallets%ROWTYPE;

    v_admin_user_id uuid;
    v_admin_wallet public.iuh_wallets%ROWTYPE;
BEGIN

    SELECT auth.uid()
    INTO v_user_id;

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Bạn chưa đăng nhập.';
    END IF;

    IF p_amount IS NULL OR p_amount <= 0 THEN
        RAISE EXCEPTION 'Số tiền thanh toán không hợp lệ.';
    END IF;

    SELECT *
    INTO v_user_wallet
    FROM public.iuh_wallets
    WHERE user_id = v_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ví IUH Wallet chưa tồn tại.';
    END IF;

    IF COALESCE(v_user_wallet.balance, 0) < p_amount THEN
        RAISE EXCEPTION
            'Số dư IUH Wallet không đủ. Cần %, hiện có %.',
            p_amount,
            v_user_wallet.balance;
    END IF;

    SELECT user_id
    INTO v_admin_user_id
    FROM public.users
    WHERE LOWER(role) = 'admin'
    LIMIT 1;

    IF v_admin_user_id IS NULL THEN
        RAISE EXCEPTION 'Không tìm thấy tài khoản Admin.';
    END IF;

    SELECT *
    INTO v_admin_wallet
    FROM public.iuh_wallets
    WHERE user_id = v_admin_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ví Admin chưa tồn tại.';
    END IF;

    /* TRỪ TIỀN SELLER */

    UPDATE public.iuh_wallets
    SET
        balance = COALESCE(balance, 0) - p_amount,
        updated_at = now()
    WHERE id = v_user_wallet.id;

    /* LỊCH SỬ SELLER */

    INSERT INTO public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description,
        created_at
    )
    VALUES (
        v_user_wallet.id,
        v_user_id,
        'payment',
        'Thanh toán phí sàn',
        p_amount,
        p_description,
        now()
    );

    /* CỘNG TIỀN ADMIN */

    UPDATE public.iuh_wallets
    SET
        balance = COALESCE(balance, 0) + p_amount,
        updated_at = now()
    WHERE id = v_admin_wallet.id;

    /* LỊCH SỬ ADMIN */

    INSERT INTO public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description,
        created_at
    )
    VALUES (
        v_admin_wallet.id,
        v_admin_user_id,
        'fee',
        'Thu phí sàn',
        p_amount,
        p_description,
        now()
    );

    RETURN jsonb_build_object(
        'success', true,
        'amount', p_amount,
        'message', 'Thanh toán phí thành công.'
    );

END;
$function$

CREATE OR REPLACE FUNCTION public.pay_service_package(p_plan_type text, p_price numeric, p_transaction_code text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user_id uuid;
    v_buyer_wallet_id bigint;
    v_admin_wallet_id bigint;
    v_admin_user_id uuid;
    v_balance numeric;
begin

    -- Người đang đăng nhập
    v_user_id := auth.uid();

    if v_user_id is null then
        return json_build_object(
            'success', false,
            'message', 'Bạn chưa đăng nhập.'
        );
    end if;


    -- Tìm ví người mua
    select id, balance
    into v_buyer_wallet_id, v_balance
    from public.iuh_wallets
    where user_id = v_user_id
    for update;

    if v_buyer_wallet_id is null then
        return json_build_object(
            'success', false,
            'message', 'Không tìm thấy Ví IUH.'
        );
    end if;


    -- Kiểm tra số dư
    if v_balance < p_price then
        return json_build_object(
            'success', false,
            'message', 'Số dư Ví IUH không đủ.'
        );
    end if;


    -- Tìm ví Admin
    select w.id, w.user_id
    into v_admin_wallet_id, v_admin_user_id
    from public.iuh_wallets w
    join public.users u
        on u.user_id = w.user_id
    where lower(u.role) = 'admin'
    limit 1
    for update;

    if v_admin_wallet_id is null then
        return json_build_object(
            'success', false,
            'message', 'Không tìm thấy ví Admin.'
        );
    end if;


    -- Trừ tiền người mua
    update public.iuh_wallets
    set
        balance = balance - p_price,
        updated_at = now()
    where id = v_buyer_wallet_id;


    -- Ghi giao dịch người mua
    insert into public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description
    )
    values (
        v_buyer_wallet_id,
        v_user_id,
        'payment',
        'Thanh toán gói dịch vụ',
        p_price,
        'Thanh toán ' || p_plan_type ||
        ' - mã giao dịch ' || p_transaction_code
    );


    -- Cộng tiền vào ví Admin
    update public.iuh_wallets
    set
        balance = balance + p_price,
        updated_at = now()
    where id = v_admin_wallet_id;


    -- Ghi doanh thu cho Admin
    insert into public.wallet_transactions (
        wallet_id,
        user_id,
        type,
        title,
        amount,
        description
    )
    values (
        v_admin_wallet_id,
        v_admin_user_id,
        'fee',
        'Gói dịch vụ',
        p_price,
        'Doanh thu ' || p_plan_type ||
        ' - mã giao dịch ' || p_transaction_code
    );


    return json_build_object(
        'success', true,
        'message', 'Thanh toán gói dịch vụ thành công.',
        'amount', p_price
    );


exception
    when others then

        return json_build_object(
            'success', false,
            'message', SQLERRM
        );

end;
$function$

CREATE OR REPLACE FUNCTION public.record_boost_qr_payment()
