CREATE OR REPLACE FUNCTION public.update_order_status(p_order_id bigint, p_new_status text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_current_status text;
    v_is_seller boolean;
begin

    if p_new_status not in (
        'pending',
        'confirmed',
        'shipping',
        'delivered',
        'completed'
    ) then
        raise exception 'Trạng thái không hợp lệ';
    end if;


    /* Kiểm tra người dùng có phải seller
       của sản phẩm trong đơn hay không */

    select exists (
        select 1
        from public.order_items oi
        where oi.order_id = p_order_id
        and oi.seller_id = auth.uid()
    )
    into v_is_seller;


    if not v_is_seller then
        raise exception 'Bạn không có quyền cập nhật đơn này';
    end if;


    /* Khóa đơn để tránh 2 người cập nhật
       cùng lúc */

    select status
    into v_current_status
    from public.orders
    where id = p_order_id
    for update;


    if v_current_status is null then
        raise exception 'Không tìm thấy đơn hàng';
    end if;


    /* Không cập nhật đơn đã hủy */

    if v_current_status = 'cancelled' then
        raise exception 'Đơn hàng đã bị hủy';
    end if;


    /* Không quay ngược trạng thái */

    if (
        case v_current_status
            when 'pending' then 0
            when 'confirmed' then 1
            when 'shipping' then 2
            when 'delivered' then 3
            when 'completed' then 4
            else -1
        end
    ) >
    (
        case p_new_status
            when 'pending' then 0
            when 'confirmed' then 1
            when 'shipping' then 2
            when 'delivered' then 3
            when 'completed' then 4
            else -1
        end
    ) then

        raise exception 'Không thể quay lại trạng thái trước đó';

    end if;


    /* Hoàn tất chỉ được chuyển từ Đã giao */

    if p_new_status = 'completed'
       and v_current_status <> 'delivered'
       and v_current_status <> 'completed'
    then

        raise exception
            'Đơn hàng phải ở trạng thái Đã giao trước khi hoàn tất';

    end if;


    update public.orders
    set
        status = p_new_status,
        updated_at = now()
    where id = p_order_id;


    insert into public.order_status_history (
        order_id,
        status,
        changed_by,
        note
    )
    values (
        p_order_id,
        p_new_status,
        auth.uid(),
        'Người bán cập nhật trạng thái đơn hàng'
    );


    return true;

end;
$function$
